\title{The Odd-Clique Obstruction for Conformability of\\ Odd-Order Regular Graphs}
\author{Aristotle}
\date{June 24, 2026}

\begin{document}
\maketitle

\begin{abstract}
Conformable colorings are a structural necessary condition for total colorability of
graphs and a central object in the study of the Total Coloring Conjecture. We isolate
and prove the combinatorial backbone governing conformability for connected
$d$-regular graphs of \emph{odd} order, the regime relevant to the conjecture that the
Conformability decision problem remains NP-complete for every fixed independence
number $\alpha(G) = k \ge 3$. Our central quantitative result is the \emph{odd-clique
counting obstruction}: if a graph of odd order $n$, all of whose independent sets have
size at most $\alpha$, admits a conformable proper coloring with $d+1$ colors, then
$n \le (d+1)\cdot\oddCap(\alpha)$, where $\oddCap(\alpha)$ is the largest odd integer
not exceeding $\alpha$. When $\alpha$ is even, this strictly improves the naive bound
$n \le (d+1)\alpha$. We further prove a \emph{degree-parity obstruction} (any
conformable odd-order regular graph has even degree $d$), the \emph{contrapositive
obstruction} (no conformable coloring exists once $(d+1)\cdot\oddCap(\alpha) < n$), and
the \emph{complement-clique identity} (every conformable color class is a clique of the
complement $G^{c}$), the structural bridge to the hardness reductions via odd-clique
packing. A tightness witness ($K_3$) shows the main bound is best possible. All results
have been formally verified in the Lean~4 proof assistant atop Mathlib.
\end{abstract}

\section{Introduction}

\subsection{Background}
Vertex coloring assigns colors to vertices of a graph $G$ so that adjacent vertices
differ; the least number of colors is the chromatic number $\chi(G)$. While
$\Delta(G)+1$ colors always suffice ($\Delta$ the maximum degree), a finer condition,
\emph{conformability}, controls the \emph{parities} of the color classes when exactly
$\Delta+1$ colors are used. Conformability arose in the study of total colorings and is
a known necessary condition associated with the Total Coloring Conjecture.

The computational complexity of recognizing conformable graphs is delicate; a finer
program locates the hardness in terms of the independence number $\alpha(G)$. The
motivating conjecture is the following.

\begin{conjecture}
For every fixed integer $k \ge 3$, the Conformability problem is NP-complete when
restricted to connected $d$-regular graphs $G$ of odd order $n$ with independence
number $\alpha(G) = k$ and maximum degree $d \ge n/2$.
\end{conjecture}

The base case $k=3$ is established by a reduction from perfect triangle packing in
$K_4$-free graphs. In the complement $G^{c}$ (with $\omega(G^{c}) = \alpha(G) = k$),
conformable color classes correspond to cliques of odd size up to $k$, so richer
packing structures encode the NP-hardness for larger $k$.

\subsection{Contributions}
This paper formalizes and proves the necessary-direction backbone for odd-order regular
graphs:
\begin{enumerate}[label=(\arabic*)]
\item odd-clique counting obstruction (Theorem~\ref{thm:bound});
\item degree-parity obstruction (Theorem~\ref{thm:even});
\item regular-graph reformulation (Theorem~\ref{thm:regular});
\item contrapositive obstruction (Theorem~\ref{thm:no});
\item complement-clique identity (Lemmas~\ref{lem:indep},~\ref{lem:clique});
\item tightness witness $K_3$ (Theorem~\ref{thm:tri}).
\end{enumerate}
All statements were verified in Lean~4 with Mathlib.

\section{Definitions}

Throughout, $G=(V,E)$ is a finite simple graph with $n=|V|$, $d(v)$ the degree of $v$,
$\Delta$ the maximum degree, and $G^{c}$ the complement.

\begin{definition}[Proper coloring]
A \emph{proper coloring} with palette $\{0,\dots,d\}$ is $c : V \to \{0,\dots,d\}$ with
$c(u)\ne c(v)$ whenever $uv \in E$. The \emph{color class} of $i$ is
$C_i = \{v : c(v)=i\}$, and $V = \bigsqcup_{i=0}^{d} C_i$.
\end{definition}

\begin{definition}[Independence number]
$S \subseteq V$ is \emph{independent} if it spans no edge. The \emph{independence
number} $\alpha(G)$ is the largest size of an independent set; we abstract it by the
hypothesis $|S|\le\alpha$ for every independent $S$.
\end{definition}

\begin{definition}[Clique]
$S$ is a \emph{clique} of a graph $H$ if its vertices are pairwise adjacent in $H$. A
set is independent in $G$ iff it is a clique of $G^{c}$; hence
$\omega(G^{c}) = \alpha(G)$.
\end{definition}

\begin{definition}[Deficiency]
$\defi(G) = \sum_{v\in V}(\Delta - d(v))$. For a $\Delta$-regular graph,
$\defi(G)=0$.
\end{definition}

\begin{definition}[Conformable coloring]
A proper coloring with $\Delta+1$ colors is \emph{conformable} if
$\bigl|\{ i : |C_i| \not\equiv n \pmod 2\}\bigr| \le \defi(G)$. For a $d$-regular graph
($\Delta=d$, $\defi(G)=0$) this is the \emph{uniform parity condition}:
$|C_i| \equiv n \pmod 2$ for every $i$.
\end{definition}

\begin{definition}[oddCap]
For $a\in\mathbb{N}$, $\oddCap(a) = a$ if $a$ is odd and $a-1$ if $a$ is even (with
$\oddCap(0)=0$); equivalently, the largest odd integer $\le a$.
\end{definition}

\section{Elementary lemma on \texorpdfstring{$\oddCap$}{oddCap}}

\begin{lemma}[\texttt{odd\_le\_oddCap}]\label{lem:oddcap}
If $x$ is odd and $x \le a$, then $x \le \oddCap(a)$.
\end{lemma}
\begin{proof}
If $a$ is odd, $\oddCap(a)=a\ge x$. If $a$ is even, write $a=2m$, $x=2t+1$; from
$2t+1\le 2m$ and parity, $2t+1\le 2m-1 = a-1 = \oddCap(a)$.
\end{proof}

\section{Structural lemmas}

\begin{lemma}[\texttt{fiber\_indep}]\label{lem:indep}
For any proper coloring $c$ with $d+1$ colors and any $i$, the class $C_i$ is
independent in $G$.
\end{lemma}
\begin{proof}
If $u,v\in C_i$ were adjacent, properness gives $c(u)\ne c(v)$, contradicting
$c(u)=i=c(v)$.
\end{proof}

\begin{lemma}[\texttt{fiber\_compl\_clique}]\label{lem:clique}
Each color class $C_i$ is a clique of the complement $G^{c}$.
\end{lemma}
\begin{proof}
$S$ independent in $G$ iff $S$ a clique of $G^{c}$; apply to $S=C_i$ via
Lemma~\ref{lem:indep}.
\end{proof}

\section{Main results}

\begin{theorem}[Odd-clique counting obstruction, \texttt{conformable\_odd\_order\_bound}]\label{thm:bound}
Let $G$ have odd order $n$, with every independent set of size $\le\alpha$. If a proper
coloring $c$ with $d+1$ colors satisfies $|C_i|\equiv n \pmod 2$ for all $i$, then
\[
n \le (d+1)\cdot\oddCap(\alpha).
\]
\end{theorem}
\begin{proof}
Fiberwise, $n=\sum_{i=0}^{d}|C_i|$. Since $n$ is odd, each $|C_i|\equiv n\equiv 1
\pmod 2$ is odd. By Lemma~\ref{lem:indep}, $|C_i|\le\alpha$; with oddness and
Lemma~\ref{lem:oddcap}, $|C_i|\le\oddCap(\alpha)$. Summing $d+1$ terms,
$n\le(d+1)\cdot\oddCap(\alpha)$.
\end{proof}

\begin{remark}
The improvement over $n\le(d+1)\alpha$ is strict iff $\alpha$ is even. With $d+1=5$,
$\alpha=4$: the naive bound gives $n\le 20$, while Theorem~\ref{thm:bound} gives
$n\le 15$, excluding $16\le n\le 20$.
\end{remark}

\begin{theorem}[Degree-parity obstruction, \texttt{conformable\_odd\_order\_even\_degree}]\label{thm:even}
Under the hypotheses of Theorem~\ref{thm:bound}, $d$ is even.
\end{theorem}
\begin{proof}
Mod $2$: $n\equiv\sum_{i=0}^{d}|C_i|\equiv (d+1)\cdot 1 = d+1\pmod 2$. As $n$ is odd,
$d+1$ is odd, so $d$ is even.
\end{proof}

\begin{theorem}[Regular reformulation, \texttt{conformable\_regular\_odd\_order\_bound}]\label{thm:regular}
Let $G$ be $d$-regular ($\Delta=d$) of odd order $n$ with $\alpha(G)\le\alpha$, and let
$c$ be conformable with $\Delta+1=d+1$ colors. Then $n\le(d+1)\cdot\oddCap(\alpha)$.
\end{theorem}
\begin{proof}
Regularity gives $\Delta=d$ and $\defi(G)=0$, so conformability collapses to the
uniform parity condition; apply Theorem~\ref{thm:bound}.
\end{proof}

\begin{theorem}[Contrapositive obstruction, \texttt{no\_conformable\_of\_card\_gt}]\label{thm:no}
If $G$ has odd order $n$ with independent sets of size $\le\alpha$ and
$(d+1)\cdot\oddCap(\alpha) < n$, then no proper coloring with $d+1$ colors is
conformable.
\end{theorem}
\begin{proof}
Contrapositive of Theorem~\ref{thm:bound}.
\end{proof}

\begin{theorem}[Tightness, \texttt{triangle\_conformable}]\label{thm:tri}
$K_3$ admits a conformable coloring attaining the bound of Theorem~\ref{thm:bound}
with equality.
\end{theorem}
\begin{proof}
$K_3$ has $n=3$ (odd), $d=2$ ($2$-regular), $\alpha=1$. Coloring vertices with
$\{0,1,2\}$ gives class sizes $1$ (odd), so the coloring is proper and conformable.
Then $(d+1)\cdot\oddCap(\alpha)=3\cdot 1 = 3 = n$, and $d=2$ is even.
\end{proof}

\section{The complement bridge to NP-hardness}

Combining Theorems~\ref{thm:bound},~\ref{thm:even} and Lemma~\ref{lem:clique}: for an
odd-order $d$-regular $G$ with $\alpha(G)=k$, a conformable coloring is exactly a
partition of $V(G)$ into $d+1$ cliques of $G^{c}$, each of odd size $\le k$. For $k=3$
the pieces are singletons and triangles, so conformability becomes constrained triangle
packing in $G^{c}$, reducing perfect triangle packing in $K_4$-free graphs and yielding
NP-completeness. For general fixed $k\ge3$ the pieces are odd cliques of size
$1,3,\dots,\oddCap(k)$, and the conjecture is that hardness persists.

\section{Algorithms}

\paragraph{Parity infeasibility certificate ($O(1)$).} Given odd $n$, degree $d$, and
$\alpha$: (1) if $d$ odd, return INFEASIBLE; (2) compute $\oddCap(\alpha)$; (3) if
$(d+1)\cdot\oddCap(\alpha)<n$, return INFEASIBLE; (4) else PARITY-FEASIBLE.

\paragraph{Complement odd-clique partition search.} Form $G^{c}$; enumerate odd cliques
of sizes $1,3,\dots,\oddCap(k)$; seek a partition of $V$ into $d+1$ such cliques. Any
partition is a conformable coloring; its absence certifies non-conformability. The
parity bound prunes to $n\le(d+1)\cdot\oddCap(k)$.

\section{Applications and discussion}

Conformability is a necessary condition tied to total colorability; the sharp odd-order
obstruction restricts which odd-order regular graphs can be conformable.
Theorems~\ref{thm:even} and~\ref{thm:no} give $O(1)$ non-conformability certificates
useful as solver preprocessing. The complement identity anchors the reduction landscape.
The results cleanly separate the constant-time parity obstructions from the NP-hard
odd-clique packing residue; $\oddCap$ makes the feasibility frontier a step function in
$\alpha$, jumping only at odd values.

\section{Future directions}

\begin{conjecture}[C1]
For a vertex-transitive $d$-regular $G$ of odd order $n$ with $\alpha(G)=k$, $G$ is
conformable iff $n\le(d+1)\cdot\oddCap(k)$ and $d$ is even. Transitivity removes local
irregularities, leaving the two proven obstructions as the only ones; sufficiency
reduces to a defect-version of Baranyai-type clique partitioning.
\end{conjecture}

\begin{conjecture}[C2]
For each fixed $k\ge3$ there is an infinite family of $d$-regular odd-order graphs with
$\alpha=k$ that are conformable but become non-conformable after deleting one vertex
orbit, the transition crossing $n=(d+1)\cdot\oddCap(k)$. Since $\oddCap(k)$ jumps by $2$
only at odd $k$, the frontier is a step function giving each $k$ its own band.
\end{conjecture}

\begin{conjecture}[C3]
Conformability of an odd-order $d$-regular $G$ is polynomial-time equivalent to deciding
whether $G^{c}$ admits a partition into exactly $d+1$ cliques each of odd size $\le k$.
The structural identity (Lemma~\ref{lem:clique}) gives one direction; the converse
packing gives the other. Both are formalized at $k=3$.
\end{conjecture}

\begin{conjecture}[C4]
Every conformable coloring of an odd-order $d$-regular graph uses all $d+1$ colors with
strictly positive odd class sizes; hence $d+1\le n$ and the class-size multiset is an
odd partition of $n$ into $d+1$ parts each $\le\oddCap(k)$. An empty class has even size
$0$, violating parity for odd $n$.
\end{conjecture}

\section{Conclusion}

We isolated and rigorously proved the parity-driven necessary conditions governing
conformability of odd-order regular graphs: the sharp bound
$n\le(d+1)\cdot\oddCap(\alpha)$, the degree-parity obstruction, an explicit
infeasibility certificate, and the complement-clique identity bridging conformability to
odd-clique packing. A triangle witness shows the central bound is tight.

\end{document}

