function FIND-ODD-CLIQUE-PARTITION(Gc, num_classes, max_size):
    odd_sizes <- [s in 1..max_size : s is odd]
    return BACKTRACK(vertices(Gc), [])

function BACKTRACK(remaining, parts):
    if remaining is empty:
        return parts if |parts| == num_classes else FAIL
    if |parts| >= num_classes: return FAIL
    pivot <- min(remaining)
    for size in odd_sizes with size <= |remaining|:
        for combo in combinations(remaining \ {pivot}, size - 1):
            clique <- {pivot} U combo
            if IS-CLIQUE(Gc, clique):
                res <- BACKTRACK(remaining \ clique, parts + [clique])
                if res != FAIL: return res
    return FAIL

